    pub next: Option<usize>,
}

pub(crate) trait MemberSource: Send + Sync {
    fn profiles(
        &self,
        term: NaiveDate,
        as_of: NaiveDate,
        current: bool,
        offset: usize,
    ) -> impl Future<Output = Result<Page<MemberProfile>>> + Send;
