use std::{future::Future, path::PathBuf, process::Stdio, time::Duration};

use chrono::{DateTime, NaiveDate, Utc};
use serde::{Deserialize, Serialize};
use serde_json::Value;
use tokio::{
    io::{AsyncBufReadExt, AsyncWriteExt, BufReader},
    process::{Child, ChildStdin, ChildStdout, Command},
    sync::Mutex,
};

use super::declarations::{interpret, source_date};
use crate::imports::core::{
    ImportError, Result,
    declarations::{Draft, Evidence},
    members::{HouseMembership, MemberHistory, MemberProfile},
    ports::{DeclarationSource, MemberSource, Page},
};

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(tag = "operation", rename_all = "kebab-case")]
pub(crate) enum Request {
    CurrentMembers {
        offset: usize,
    },
    MemberCandidates {
        term_start: NaiveDate,
        as_of: NaiveDate,
        offset: usize,
    },
    MemberHistories {
        ids: Vec<i32>,
    },
    Declarations {
        member: i32,
        offset: usize,
    },
    Parent {
        member: i32,
        parent: i32,
    },
}

#[derive(Debug, Clone, Deserialize, Serialize)]
pub(crate) struct Response {
    pub payload: Value,
    pub fetched_at: DateTime<Utc>,
    pub context: String,
}

pub(crate) trait Transport: Send + Sync {
    fn fetch(&self, request: Request) -> impl Future<Output = Result<Response>> + Send;
}

pub(crate) struct Parliament<T>(pub T);

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Envelope {
    items: Vec<Value>,
    total_results: usize,
    #[serde(rename = "skip")]
    _skip: usize,
}

fn envelope(
    response: &Response,
    offset: usize,
    members: bool,
) -> Result<(Vec<Value>, Option<usize>)> {
    let page: Envelope = serde_json::from_value(response.payload.clone())
        .map_err(|e| ImportError::Invalid(format!("Invalid Parliament page: {e}")))?;
    if members && page.items.is_empty() && offset < page.total_results {
        return Err(ImportError::Invalid(
            "Search ended before all advertised members were returned".into(),
        ));
    }
    let next = offset
        .checked_add(page.items.len())
        .ok_or_else(|| ImportError::Invalid("Invalid page size".into()))?;
    let more = !page.items.is_empty() && next < page.total_results;
    Ok((page.items, more.then_some(next)))
}

#[derive(Deserialize)]
struct Party {
    id: Option<i32>,
    name: Option<String>,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Membership {
    house: i16,
    membership_from: Option<String>,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Profile {
    id: i32,
    name_display_as: String,
    latest_party: Option<Party>,
    latest_house_membership: Membership,
}

fn profile(raw: Value) -> Result<MemberProfile> {
    let p: Profile = serde_json::from_value(raw["value"].clone())
        .map_err(|e| ImportError::Invalid(format!("Invalid member: {e}")))?;
    let (party_id, party_name) = p.latest_party.map_or((None, None), |p| (p.id, p.name));
    let member = MemberProfile {
        id: p.id,
        name: p.name_display_as,
        party_id,
        party_name,
        house: p.latest_house_membership.house,
        membership_from: p.latest_house_membership.membership_from,
    };
    member.validate()?;
    Ok(member)
}

impl<T: Transport> MemberSource for Parliament<T> {
    async fn profiles(
        &self,
        term: NaiveDate,
        as_of: NaiveDate,
        current: bool,
        offset: usize,
    ) -> Result<Page<MemberProfile>> {
        let request = if current {
            Request::CurrentMembers { offset }
        } else {
            Request::MemberCandidates {
                term_start: term,
                as_of,
                offset,
            }
        };
        let response = self.0.fetch(request).await?;
        let (items, next) = envelope(&response, offset, true)?;
        Ok(Page {
            entries: items.into_iter().map(profile).collect::<Result<_>>()?,
            next,
        })
    }
    async fn histories(&self, ids: &[i32]) -> Result<Vec<MemberHistory>> {
        if ids.is_empty() || ids.len() > 100 {
            return Err(ImportError::Invalid(
                "History requests need between 1 and 100 IDs".into(),
            ));
        }
        let response = self
            .0
            .fetch(Request::MemberHistories { ids: ids.to_vec() })
            .await?;
        let items = response
            .payload
            .as_array()
            .ok_or_else(|| ImportError::Invalid("Invalid history envelope".into()))?;
        items
            .iter()
            .map(|item| {
                #[derive(Deserialize)]
                #[serde(rename_all = "camelCase")]
                struct History {
                    id: i32,
                    house_membership_history: Vec<Value>,
                }
                let history: History = serde_json::from_value(item["value"].clone())
                    .map_err(|e| ImportError::Invalid(format!("Invalid history: {e}")))?;
                let memberships = history
                    .house_membership_history
                    .iter()
                    .map(|m| {
                        let house = m["house"]
                            .as_i64()
                            .and_then(|h| i16::try_from(h).ok())
                            .filter(|h| [1, 2].contains(h))
                            .ok_or_else(|| ImportError::Invalid("Invalid history House".into()))?;
                        let start = source_date(&m["membershipStartDate"], "membershipStartDate")
                            .map_err(|e| ImportError::Invalid(e.to_string()))?;
                        let end = if m["membershipEndDate"].is_null() {
                            None
                        } else {
                            Some(
                                source_date(&m["membershipEndDate"], "membershipEndDate")
                                    .map_err(|e| ImportError::Invalid(e.to_string()))?,
                            )
                        };
                        Ok(HouseMembership { house, start, end })
                    })
                    .collect::<Result<Vec<_>>>()?;
                if history.id <= 0 || memberships.is_empty() {
                    return Err(ImportError::Invalid("Invalid member history".into()));
                }
                Ok(MemberHistory {
                    id: history.id,
                    memberships,
                })
            })
            .collect()
    }
}

fn evidence(items: Vec<Value>, response: &Response) -> Vec<Evidence> {
    items
        .into_iter()
        .map(|payload| Evidence {
            source_id: payload
                .get("id")
                .and_then(Value::as_i64)
                .and_then(|n| i32::try_from(n).ok()),
            payload,
            fetched_at: response.fetched_at,
            context: response.context.clone(),
        })
        .collect()
}

impl<T: Transport> DeclarationSource for Parliament<T> {
    async fn declarations(&self, member: i32, offset: usize) -> Result<Page<Evidence>> {
        let response = self
            .0
            .fetch(Request::Declarations { member, offset })
            .await?;
        let (items, next) = envelope(&response, offset, false)?;
        Ok(Page {
            entries: evidence(items, &response),
            next,
        })
    }
    async fn parents(&self, member: i32, parent: i32) -> Result<Vec<Evidence>> {
        let response = self.0.fetch(Request::Parent { member, parent }).await?;
        let (items, _) = envelope(&response, 0, false)?;
        Ok(evidence(items, &response))
    }
    fn interpret(&self, evidence: &Evidence) -> Result<Draft> {
        interpret(&evidence.payload)
    }
}

struct Worker {
    _child: Child,
    input: ChildStdin,
    output: BufReader<ChildStdout>,
}
pub(crate) struct CliTransport {
    python: PathBuf,
    directory: PathBuf,
    worker: Mutex<Option<Worker>>,
}

impl CliTransport {
    pub fn new(python: PathBuf, directory: PathBuf) -> Self {
        Self {
            python,
            directory,
            worker: Mutex::new(None),
        }
    }
    fn start(&self) -> Result<Worker> {
        // Preserve the venv executable symlink: resolving it selects the base Python.
        let python = std::path::absolute(&self.python)
            .map_err(|e| ImportError::source_failure("Python executable is unavailable", e))?;
        let mut command = Command::new(python);
        command
            .args(["-m", "exposed", "source"])
            .current_dir(&self.directory)
            .env_clear()
            .env("PYTHONPATH", "src")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .kill_on_drop(true);
        for key in [
            "PATH",
            "SSL_CERT_FILE",
            "HTTPS_PROXY",
            "HTTP_PROXY",
            "NO_PROXY",
        ] {
            if let Some(value) = std::env::var_os(key) {
                command.env(key, value);
            }
        }
        let mut child = command
            .spawn()
            .map_err(|e| ImportError::source_failure("Could not start Python API worker", e))?;
        let input = child
            .stdin
            .take()
            .ok_or_else(|| ImportError::Source("Worker stdin unavailable".into()))?;
        let output = BufReader::new(
            child
                .stdout
                .take()
                .ok_or_else(|| ImportError::Source("Worker stdout unavailable".into()))?,
        );
        Ok(Worker {
            _child: child,
            input,
            output,
        })
    }
}

impl Transport for CliTransport {
    async fn fetch(&self, request: Request) -> Result<Response> {
        tokio::time::timeout(Duration::from_secs(240), async {
            let mut slot = self.worker.lock().await;
            if slot.is_none() {
                *slot = Some(self.start()?);
            }
            let worker = slot
                .as_mut()
                .ok_or_else(|| ImportError::Source("Worker did not start".into()))?;
            let mut data = serde_json::to_vec(&request)
                .map_err(|e| ImportError::source_failure("Could not encode worker request", e))?;
            data.push(b'\n');
            worker
                .input
                .write_all(&data)
                .await
                .map_err(|e| ImportError::source_failure("Worker input closed", e))?;
            worker
                .input
                .flush()
                .await
                .map_err(|e| ImportError::source_failure("Worker input closed", e))?;
            let mut line = String::new();
            worker
                .output
                .read_line(&mut line)
                .await
                .map_err(|e| ImportError::source_failure("Worker output closed", e))?;
            let value: Value = serde_json::from_str(&line)
                .map_err(|e| ImportError::source_failure("Invalid worker response", e))?;
            if let Some(error) = value.get("error").and_then(Value::as_str) {
                return Err(ImportError::Source(error.to_owned()));
            }
            serde_json::from_value(value)
                .map_err(|e| ImportError::source_failure("Invalid evidence envelope", e))
        })
        .await
        .map_err(|e| ImportError::source_failure("Python API worker timed out", e))?
    }
}
use std::{collections::HashMap, str::FromStr};

use bigdecimal::BigDecimal;
use chrono::{DateTime, NaiveDate, NaiveDateTime};
use serde::Deserialize;
use serde_json::{Map, Value};

use crate::imports::core::{
    ImportError, Result,
    declarations::{Draft, FunderCandidates, Funding, funder_attribution, latest_version},
};

pub(crate) fn invalid(path: &str, value: &Value, message: &str) -> ImportError {
    ImportError::Rejected(format!("{path}: {message}; input={value}"))
}

pub(crate) fn source_date(value: &Value, path: &str) -> Result<NaiveDate> {
    let text = value
        .as_str()
        .ok_or_else(|| invalid(path, value, "expected an ISO date"))?;
    if let Ok(date) = NaiveDate::parse_from_str(text, "%Y-%m-%d") {
        return Ok(date);
    }
    if let Ok(date) = DateTime::parse_from_rfc3339(text) {
        return Ok(date.date_naive());
    }
    for format in ["%Y-%m-%dT%H:%M:%S%.f", "%Y-%m-%d %H:%M:%S%.f"] {
        if let Ok(date) = NaiveDateTime::parse_from_str(text, format) {
            return Ok(date.date());
        }
    }
    Err(invalid(path, value, "expected an ISO date or datetime"))
}

fn positive(value: &Value, path: &str) -> Result<i32> {
    value
        .as_i64()
        .and_then(|n| i32::try_from(n).ok())
        .filter(|n| *n > 0)
        .ok_or_else(|| invalid(path, value, "expected a positive integer"))
}

fn nonblank(value: &Value, path: &str) -> Result<String> {
    value
        .as_str()
        .filter(|s| !s.trim().is_empty())
        .map(str::to_owned)
        .ok_or_else(|| invalid(path, value, "expected a nonblank string"))
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Field {
    name: String,
    #[serde(rename = "type")]
    kind: Option<String>,
    type_info: Option<Map<String, Value>>,
    #[serde(default)]
    value: Value,
    values: Option<Vec<Vec<Field>>>,
}

impl Field {
    fn text(&self, path: &str) -> Result<Option<String>> {
        if self.value.is_null() {
            return Ok(None);
        }
        self.value
            .as_str()
            .map(|s| (!s.trim().is_empty()).then(|| s.to_owned()))
            .ok_or_else(|| invalid(path, &self.value, "expected a string"))
    }

    fn check_shape(&self, path: &str, allowed: bool, nested: bool) -> Result<()> {
        let currency = self
            .type_info
            .as_ref()
            .is_some_and(|m| m.contains_key("currencyCode"));
        let financial =
            ["Value", "PaymentType", "Donors"].contains(&self.name.as_str()) || currency;
        if financial
            && (!allowed || (currency && self.name != "Value") || (nested && self.name == "Donors"))
        {
            return Err(invalid(
                path,
                &self.value,
                "unsupported funding field or nesting",
            ));
        }
        for (i, group) in self.values.iter().flatten().enumerate() {
            if self.name == "Donors" && group.is_empty() {
                return Err(invalid(path, &self.value, "empty donor group"));
            }
            for (j, field) in group.iter().enumerate() {
                field.check_shape(
                    &format!("{path}.values.{i}.{j}.{}", field.name),
                    allowed && self.name == "Donors",
                    true,
                )?;
            }
        }
        Ok(())
    }
}

fn funding(fields: &[Field], path: &str, donor_group: bool) -> Result<Funding> {
    let index: HashMap<_, _> = fields
        .iter()
        .enumerate()
        .map(|(i, f)| (f.name.as_str(), (i, f)))
        .collect();
    if index.len() != fields.len() {
        return Err(ImportError::Rejected(format!(
            "{path}: repeated field names"
        )));
    }
    let text = |name: &str| -> Result<Option<String>> {
        match index.get(name) {
            Some((i, f)) => f.text(&format!("{path}.{i}.{name}.value")),
            None => Ok(None),
        }
    };
    let mut amount = None;
    let mut currency = None;
    if let Some((i, value)) = index.get("Value") {
        let location = format!("{path}.{i}.Value");
        if value.kind.as_deref() != Some("Decimal") {
            return Err(invalid(
                &location,
                &value.value,
                "expected Decimal monetary field",
            ));
        }
        if !value.value.is_null() {
            let raw = match &value.value {
                Value::String(text) => text.clone(),
                Value::Number(number) => {
                    let raw = number.to_string();
                    // Python accepts arbitrary-size JSON integers, but rejects JSON floats.
                    if raw.contains(['.', 'e', 'E']) {
                        return Err(invalid(&location, &value.value, "unsupported amount"));
                    }
                    raw
                }
                _ => return Err(invalid(&location, &value.value, "unsupported amount")),
            };
            let unsigned = raw.strip_prefix('-').unwrap_or(&raw);
            let parts: Vec<_> = unsigned.split('.').collect();
            if parts.len() > 2
                || parts
                    .iter()
                    .any(|p| p.is_empty() || !p.bytes().all(|c| c.is_ascii_digit()))
            {
                return Err(invalid(&location, &value.value, "unsupported amount"));
            }
            amount = Some(
                BigDecimal::from_str(&raw)
                    .map_err(|_| invalid(&location, &value.value, "unsupported amount"))?,
            );
        }
        if let Some(code) = value
            .type_info
            .as_ref()
            .and_then(|m| m.get("currencyCode"))
            .filter(|v| !v.is_null())
        {
            currency = Some(
                code.as_str()
                    .ok_or_else(|| invalid(&location, code, "expected a currency string"))?
                    .to_owned(),
            );
        }
    }
    let (funder_name, funder_kind, company_number) = funder_attribution(
        FunderCandidates {
            ultimate_payer: text("UltimatePayerName"),
            donor: text("DonorName"),
            payer: text("PayerName"),
            group_donor: if donor_group { text("Name") } else { Ok(None) },
        },
        text("DonorStatus"),
        text("DonorCompanyIdentifier"),
    )?;
    Ok(Funding {
        funder_name,
        funder_kind,
        company_number,
        amount,
        currency,
        payment_type: text("PaymentType")?,
    })
}

pub(crate) fn interpret(raw: &Value) -> Result<Draft> {
    let id = positive(&raw["id"], "id")?;
    let member_source_id = positive(
        &raw["registrant"]["memberDetail"]["id"],
        "registrant.memberDetail.id",
    )?;
    if raw["registrant"]["type"] != "Member" || raw["category"]["type"] != "Commons" {
        return Err(invalid(
            "registrant/category",
            raw,
            "expected a Commons Member declaration",
        ));
    }
    let category_id = positive(&raw["category"]["id"], "category.id")?;
    let category_name = nonblank(&raw["category"]["name"], "category.name")?;
    let parent_id = if raw["parentInterestId"].is_null() {
        None
    } else {
        Some(positive(&raw["parentInterestId"], "parentInterestId")?)
    };
    let versions = raw["versions"]
        .as_array()
        .ok_or_else(|| invalid("versions", &raw["versions"], "expected versions"))?;
    let published = versions
        .iter()
        .enumerate()
        .map(|(i, v)| {
            let date = source_date(
                &v["register"]["publishedDate"],
                &format!("versions.{i}.register.publishedDate"),
            )?;
            let mut content = v
                .as_object()
                .ok_or_else(|| invalid("versions", v, "expected version object"))?
                .clone();
            content.remove("register");
            content.remove("links");
            Ok((date, Value::Object(content)))
        })
        .collect::<Result<Vec<_>>>()?;
    let selected = latest_version(&published)?;
    let version = &versions[selected];
    let path = format!("versions.{selected}.fields");
    let fields: Vec<Field> = serde_json::from_value(version["fields"].clone())
        .map_err(|e| invalid(&path, &version["fields"], &e.to_string()))?;
    let mut entries = Vec::new();
    for (i, field) in fields.iter().enumerate() {
        field.check_shape(&format!("{path}.{i}.{}", field.name), true, false)?;
    }
    if fields
        .iter()
        .any(|f| ["Value", "PaymentType"].contains(&f.name.as_str()))
    {
        entries.push(funding(&fields, &path, false)?);
    }
    for (i, field) in fields
        .iter()
        .enumerate()
        .filter(|(_, f)| f.name == "Donors")
    {
        let groups = field
            .values
            .as_ref()
            .ok_or_else(|| invalid(&path, &field.value, "expected donor groups"))?;
        for (j, group) in groups.iter().enumerate() {
            entries.push(funding(
                group,
                &format!("{path}.{i}.Donors.values.{j}"),
                true,
            )?);
        }
    }
    let payer = funding(&fields, &path, false)?.funder_name;
    let mut ultimate_payer_differs = false;
    if parent_id.is_some() {
        if let Some(field) = fields.iter().find(|f| f.name == "IsUltimatePayerDifferent") {
            if !field.value.is_null() && !field.value.is_boolean() {
                return Err(invalid(&path, &field.value, "expected a boolean"));
            }
            ultimate_payer_differs = field.value == true;
        }
    }
    let registration_date = if version["registrationDate"].is_null() {
        None
    } else {
        Some(source_date(
            &version["registrationDate"],
            "registrationDate",
        )?)
    };
    Ok(Draft {
        id,
        member_source_id,
        category_id,
        category_name,
        registration_date,
        funding: entries,
        payer,
        parent_id,
        ultimate_payer_differs,
    })
}
use chrono::{DateTime, NaiveDate, Utc};
use sqlx::{PgPool, Postgres, Row, Transaction, pool::PoolConnection};
use std::collections::BTreeMap;
use uuid::Uuid;

use crate::imports::core::{
    ImportError, Result,
    declarations::{Accepted, Funding, Payment, merge_funder_metadata, same_payments},
    members::{Member, validate_configured_term},
    ports::{ImportStore, NotificationQueue},
    refresh::{Changes, RefreshState},
};

fn database(error: sqlx::Error) -> ImportError {
    ImportError::Storage(Box::new(error))
}
fn midnight(date: NaiveDate) -> DateTime<Utc> {
    date.and_time(chrono::NaiveTime::MIN).and_utc()
}

#[derive(Clone)]
pub(crate) struct PostgresStore {
    pool: PgPool,
}
impl PostgresStore {
    pub fn new(pool: PgPool) -> Self {
        Self { pool }
    }
}

impl ImportStore for PostgresStore {
    type Lease = PoolConnection<Postgres>;
    async fn acquire(&self) -> Result<Self::Lease> {
        let mut connection = self.pool.acquire().await.map_err(database)?;
        let acquired: bool = sqlx::query_scalar("SELECT pg_try_advisory_lock(20260925, 1)")
            .fetch_one(&mut *connection)
            .await
            .map_err(database)?;
        if !acquired {
            return Err(ImportError::Busy);
        }
        // Session locks must never be returned to the pool. Closing also handles cancellation.
        connection.close_on_drop();
        Ok(connection)
    }

    async fn member_batch(&self, term: NaiveDate, members: &[Member]) -> Result<Changes> {
        let mut tx = self.pool.begin().await.map_err(database)?;
        let dates: Vec<DateTime<Utc>> =
            sqlx::query_scalar("SELECT term_start FROM exposed.parliament_terms")
                .fetch_all(&mut *tx)
                .await
                .map_err(database)?;
        validate_configured_term(term, dates.into_iter().map(|d| d.date_naive()))?;
        let term_id: Uuid = sqlx::query_scalar("INSERT INTO exposed.parliament_terms (term_start) VALUES ($1) ON CONFLICT (term_start) DO UPDATE SET term_start = EXCLUDED.term_start RETURNING id")
            .bind(midnight(term)).fetch_one(&mut *tx).await.map_err(database)?;
        let mut changes = Changes::default();
        for member in members {
            let p = member.profile();
            let previous = sqlx::query("SELECT name, party_id, party_name, latest_house, latest_membership_from, is_current_commons FROM exposed.members WHERE parliament_member_id = $1")
                .bind(p.id).fetch_optional(&mut *tx).await.map_err(database)?;
            match previous {
                None => changes.inserted += 1,
                Some(row)
                    if row.get::<String, _>("name") == p.name
                        && row.get::<Option<i32>, _>("party_id") == p.party_id
                        && row.get::<Option<String>, _>("party_name") == p.party_name
                        && row.get::<i16, _>("latest_house") == p.house
                        && row.get::<Option<String>, _>("latest_membership_from")
                            == p.membership_from
                        && row.get::<bool, _>("is_current_commons") == member.is_current() =>
                {
                    changes.unchanged += 1
                }
                Some(_) => changes.updated += 1,
            }
            let member_id: Uuid = sqlx::query_scalar("INSERT INTO exposed.members (parliament_member_id, name, party_id, party_name, latest_house, latest_membership_from, is_current_commons) VALUES ($1,$2,$3,$4,$5,$6,$7) ON CONFLICT (parliament_member_id) DO UPDATE SET name=EXCLUDED.name, party_id=EXCLUDED.party_id, party_name=EXCLUDED.party_name, latest_house=EXCLUDED.latest_house, latest_membership_from=EXCLUDED.latest_membership_from, is_current_commons=EXCLUDED.is_current_commons RETURNING id")
                .bind(p.id).bind(&p.name).bind(p.party_id).bind(&p.party_name).bind(p.house).bind(&p.membership_from).bind(member.is_current())
                .fetch_one(&mut *tx).await.map_err(database)?;
            for period in member.periods() {
                sqlx::query("INSERT INTO exposed.member_terms (member_id,term_id,house,source_start_date,source_end_date,served_from,served_until) VALUES ($1,$2,1,$3,$4,$5,$4) ON CONFLICT (member_id,term_id,house,source_start_date) DO UPDATE SET source_end_date=EXCLUDED.source_end_date, served_from=EXCLUDED.served_from, served_until=EXCLUDED.served_until")
                    .bind(member_id).bind(term_id).bind(midnight(period.source_start)).bind(period.end.map(midnight)).bind(midnight(period.served_from))
                    .execute(&mut *tx).await.map_err(database)?;
            }
            let starts: Vec<_> = member
                .periods()
                .iter()
                .map(|p| midnight(p.source_start))
                .collect();
            sqlx::query("DELETE FROM exposed.member_terms WHERE member_id=$1 AND term_id=$2 AND NOT (source_start_date = ANY($3))")
                .bind(member_id).bind(term_id).bind(starts).execute(&mut *tx).await.map_err(database)?;
        }
        tx.commit().await.map_err(database)?;
        Ok(changes)
    }

    async fn cohort(&self, term: NaiveDate) -> Result<BTreeMap<i32, Uuid>> {
        let rows = sqlx::query("SELECT DISTINCT m.id,m.parliament_member_id FROM exposed.members m JOIN exposed.member_terms s ON s.member_id=m.id JOIN exposed.parliament_terms t ON t.id=s.term_id WHERE t.term_start=$1 AND s.house=1 ORDER BY m.parliament_member_id")
            .bind(midnight(term)).fetch_all(&self.pool).await.map_err(database)?;
        Ok(rows
            .into_iter()
            .map(|r| (r.get("parliament_member_id"), r.get("id")))
            .collect())
    }

    async fn publish(&self, member: Uuid, declarations: &[Accepted]) -> Result<()> {
        let mut tx = self.pool.begin().await.map_err(database)?;
        for accepted in declarations {
            write_declaration(&mut tx, member, accepted).await?;
        }
        tx.commit().await.map_err(database)
    }

    async fn refresh_state(&self, term: NaiveDate) -> Result<RefreshState> {
        let row = sqlx::query("SELECT * FROM exposed.import_refresh_state WHERE term_start=$1")
            .bind(midnight(term))
            .fetch_optional(&self.pool)
            .await
            .map_err(database)?;
        Ok(row.map_or_else(RefreshState::default, |r| RefreshState {
            last_completed: r.get("last_completed"),
            last_attempt: r.get("last_attempt"),
            next_attempt: r.get("next_attempt"),
            outcome: r.get("outcome"),
            rejected: r.get::<i32, _>("rejected") as usize,
            failures: r.get::<i32, _>("failures") as u32,
            new_members: r.get("new_members"),
        }))
    }
    async fn record_refresh(&self, term: NaiveDate, state: &RefreshState) -> Result<()> {
        sqlx::query("INSERT INTO exposed.import_refresh_state (term_start,last_completed,last_attempt,next_attempt,outcome,rejected,failures,new_members) VALUES ($1,$2,$3,$4,$5,$6,$7,$8) ON CONFLICT (term_start) DO UPDATE SET last_completed=EXCLUDED.last_completed,last_attempt=EXCLUDED.last_attempt,next_attempt=EXCLUDED.next_attempt,outcome=EXCLUDED.outcome,rejected=EXCLUDED.rejected,failures=EXCLUDED.failures,new_members=EXCLUDED.new_members")
            .bind(midnight(term)).bind(state.last_completed).bind(state.last_attempt).bind(state.next_attempt).bind(&state.outcome)
            .bind(i32::try_from(state.rejected).unwrap_or(i32::MAX)).bind(i32::try_from(state.failures).unwrap_or(i32::MAX)).bind(&state.new_members)
            .execute(&self.pool).await.map_err(database)?;
        Ok(())
    }
}

async fn write_funder(tx: &mut Transaction<'_, Postgres>, entry: &Funding) -> Result<Option<Uuid>> {
    let Some(name) = &entry.funder_name else {
        return Ok(None);
    };
    let previous = sqlx::query(
        "SELECT funder_kind,company_number FROM exposed.funders WHERE funder_name=$1 FOR UPDATE",
    )
    .bind(name)
    .fetch_optional(&mut **tx)
    .await
    .map_err(database)?;
    let (kind, number) = previous.map_or((None, None), |r| {
        (r.get("funder_kind"), r.get("company_number"))
    });
    let (kind, number) = merge_funder_metadata(entry, kind, number);
    let id = sqlx::query_scalar("INSERT INTO exposed.funders (funder_name,funder_kind,company_number) VALUES ($1,$2,$3) ON CONFLICT (funder_name) DO UPDATE SET funder_kind=EXCLUDED.funder_kind,company_number=EXCLUDED.company_number RETURNING id")
        .bind(name).bind(kind).bind(number).fetch_one(&mut **tx).await.map_err(database)?;
    Ok(Some(id))
}

async fn write_declaration(
    tx: &mut Transaction<'_, Postgres>,
    member: Uuid,
    accepted: &Accepted,
) -> Result<()> {
    let d = accepted.declaration.draft();
    sqlx::query("INSERT INTO exposed.declarations (source_declaration_id,member_id,category_id,category_name,registration_date,fetched_at) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (source_declaration_id) DO UPDATE SET member_id=EXCLUDED.member_id,category_id=EXCLUDED.category_id,category_name=EXCLUDED.category_name,registration_date=EXCLUDED.registration_date,fetched_at=EXCLUDED.fetched_at")
        .bind(d.id).bind(member).bind(d.category_id).bind(&d.category_name).bind(d.registration_date.map(midnight)).bind(accepted.fetched_at)
        .execute(&mut **tx).await.map_err(database)?;
    let mut payments = Vec::new();
    for entry in &d.funding {
        payments.push(Payment {
            funder_id: write_funder(tx, entry).await?,
            amount: entry.amount.clone(),
            currency: entry.currency.clone(),
            payment_type: entry.payment_type.clone(),
        });
    }
    let rows = sqlx::query("SELECT funder_id,amount,currency,payment_type FROM exposed.funding_entries WHERE source_declaration_id=$1")
        .bind(d.id).fetch_all(&mut **tx).await.map_err(database)?;
    let previous: Vec<_> = rows
        .into_iter()
        .map(|r| Payment {
            funder_id: r.get("funder_id"),
            amount: r.get("amount"),
            currency: r.get("currency"),
            payment_type: r.get("payment_type"),
        })
        .collect();
    if same_payments(&payments, &previous) {
        return Ok(());
    }
    sqlx::query("DELETE FROM exposed.funding_entries WHERE source_declaration_id=$1")
        .bind(d.id)
        .execute(&mut **tx)
        .await
        .map_err(database)?;
    for p in payments {
        sqlx::query("INSERT INTO exposed.funding_entries (source_declaration_id,funder_id,amount,currency,payment_type) VALUES ($1,$2,$3,$4,$5)")
            .bind(d.id).bind(p.funder_id).bind(p.amount).bind(p.currency).bind(p.payment_type).execute(&mut **tx).await.map_err(database)?;
    }
    Ok(())
}

impl NotificationQueue for PostgresStore {
    async fn enqueue(&self, key: &str, message: &str) -> Result<()> {
        sqlx::query("INSERT INTO exposed.import_notifications (event_key,message) VALUES ($1,$2) ON CONFLICT (event_key) DO NOTHING")
            .bind(key).bind(message).execute(&self.pool).await.map_err(database)?;
        Ok(())
    }
    async fn pending(&self, now: DateTime<Utc>) -> Result<Option<(Uuid, String, i32)>> {
        let row = sqlx::query("UPDATE exposed.import_notifications SET next_attempt=$1 + INTERVAL '2 minutes' WHERE id=(SELECT id FROM exposed.import_notifications WHERE delivered_at IS NULL AND next_attempt <= $1 ORDER BY next_attempt,id FOR UPDATE SKIP LOCKED LIMIT 1) RETURNING id,message,attempts")
            .bind(now).fetch_optional(&self.pool).await.map_err(database)?;
        Ok(row.map(|r| (r.get("id"), r.get("message"), r.get("attempts"))))
    }
    async fn delivered(&self, id: Uuid) -> Result<()> {
        sqlx::query("UPDATE exposed.import_notifications SET delivered_at=now() WHERE id=$1")
            .bind(id)
            .execute(&self.pool)
            .await
            .map_err(database)?;
        Ok(())
    }
    async fn retry_notification(&self, id: Uuid, next: DateTime<Utc>) -> Result<()> {
        sqlx::query("UPDATE exposed.import_notifications SET attempts=attempts+1,next_attempt=$2 WHERE id=$1")
            .bind(id).bind(next).execute(&self.pool).await.map_err(database)?;
        Ok(())
    }
}
use crate::imports::{
    config::WhatsAppConfig,
    core::{ImportError, Result, ports::Notifications},
};
use anyhow::Context;
use serde_json::json;
use std::time::Duration;

pub(crate) struct WhatsApp {
    client: reqwest::Client,
    config: WhatsAppConfig,
    token: String,
}
impl WhatsApp {
    pub fn new(config: WhatsAppConfig) -> anyhow::Result<Self> {
        let token = std::env::var(&config.token_env)
            .context("WhatsApp token environment variable is missing")?;
        anyhow::ensure!(!token.is_empty(), "WhatsApp token is empty");
        anyhow::ensure!(
            config.api_version.starts_with('v')
                && config.api_version[1..]
                    .chars()
                    .all(|c| c.is_ascii_digit() || c == '.'),
            "Invalid Graph API version"
        );
        anyhow::ensure!(
            !config.phone_number_id.is_empty()
                && config.phone_number_id.chars().all(|c| c.is_ascii_digit()),
            "Invalid WhatsApp sender ID"
        );
        Ok(Self {
            client: reqwest::Client::builder()
                .timeout(Duration::from_secs(30))
                .build()?,
            config,
            token,
        })
    }
}
impl Notifications for WhatsApp {
    async fn deliver(&self, message: &str) -> Result<()> {
        let url = format!(
            "https://graph.facebook.com/{}/{}/messages",
            self.config.api_version, self.config.phone_number_id
        );
        let response = self
            .client
            .post(url)
            .bearer_auth(&self.token)
            .json(&json!({
                "messaging_product":"whatsapp", "to":self.config.recipient, "type":"template",
                "template": {"name":self.config.template,"language":{"code":self.config.language},
                    "components":[{"type":"body","parameters":[{"type":"text","text":message}]}]}
            }))
            .send()
            .await
            .map_err(|e| ImportError::source_failure("WhatsApp transport failed", e))?;
        let status = response.status();
        response.error_for_status().map_err(|e| {
            ImportError::source_failure(format!("WhatsApp returned HTTP {}", status.as_u16()), e)
        })?;
        Ok(())
    }
}

