                command.env(key, value);
            }
        }
        let mut child = command
            .spawn()
            .map_err(|e| ImportError::source_failure("Could not start Python API worker", e))?;
        let input = child
            .stdin
            .take()
            .ok_or_else(|| ImportError::Source("Worker stdin unavailable".into()))?;
        let output = BufReader::new(
            child
                .stdout
                .take()
                .ok_or_else(|| ImportError::Source("Worker stdout unavailable".into()))?,
        );
        Ok(Worker {
            _child: child,
            input,
            output,
        })
    }
}

impl Transport for CliTransport {
    async fn fetch(&self, request: Request) -> Result<Response> {
        tokio::time::timeout(Duration::from_secs(240), async {
            let mut slot = self.worker.lock().await;
            if slot.is_none() {
                *slot = Some(self.start()?);
            }
            let worker = slot
                .as_mut()
                .ok_or_else(|| ImportError::Source("Worker did not start".into()))?;
            let mut data = serde_json::to_vec(&request)
                .map_err(|e| ImportError::source_failure("Could not encode worker request", e))?;
            data.push(b'\n');
            worker
                .input
                .write_all(&data)
                .await
                .map_err(|e| ImportError::source_failure("Worker input closed", e))?;
            worker
                .input
                .flush()
                .await
                .map_err(|e| ImportError::source_failure("Worker input closed", e))?;
            let mut line = String::new();
            worker
                .output
                .read_line(&mut line)
                .await
