        let message = match result {
            Ok(result) => json!({"result":result}),
            Err(error) => {
                eprintln!("Operator import: {error:?}");
                json!({"error":error.to_string()})
            }
        };
        let _ = tx.send(Event::Finished(message)).await;
    });
    let session = Arc::new(Session {
        task,
        exchange: Mutex::new(Exchange {
            events,
            pending: None,
            sequence: 0,
            last_submission: None,
            message: None,
        }),
    });
    sessions.insert(
        id,
        RegisteredSession {
            session: Arc::clone(&session),
            touched: Instant::now(),
        },
    );
    drop(sessions);
    let message = session.exchange.lock().await.message().await;
    Ok(Json(message))
}

#[derive(Deserialize)]
struct Submission {
    sequence: u64,
    response: Response,
}
async fn evidence(
    State(state): State<AdminState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
    Json(body): Json<Submission>,
) -> HttpResult {
    state.authorize(&headers)?;
    let mut sessions = state.sessions.lock().await;
    let session = sessions.get_mut(&id).ok_or_else(|| {
        bad(
            StatusCode::NOT_FOUND,
            "Import session expired; rerun safely",
        )
    })?;
    session.touched = Instant::now();
    let session = Arc::clone(&session.session);
    drop(sessions);
    let mut session = session.exchange.lock().await;
    let raw = json!(body.response);
    if body.sequence.checked_add(1) == Some(session.sequence)
        && session.last_submission.as_ref() == Some(&raw)
    {
        return Ok(Json(session.message().await));
    }
    if body.sequence != session.sequence {
        return Err(bad(StatusCode::CONFLICT, "Unexpected evidence sequence"));
    }
    let reply = session
        .pending
        .take()
        .ok_or_else(|| bad(StatusCode::CONFLICT, "No evidence requested"))?;
    reply
        .send(body.response)
        .map_err(|_| bad(StatusCode::GONE, "Import source session expired"))?;
    session.sequence += 1;
    session.last_submission = Some(raw);
    session.message = None;
    Ok(Json(session.message().await))
}

async fn cancel(
    State(state): State<AdminState>,
    Path(id): Path<Uuid>,
    headers: HeaderMap,
) -> HttpResult {
    state.authorize(&headers)?;
    if let Some(session) = state.sessions.lock().await.remove(&id) {
        // The exchange may be waiting on publication. Abort without taking that lock.
        session.session.task.abort();
    }
    Ok(Json(json!({"status":"cancelled"})))
}
async fn status(State(state): State<AdminState>, headers: HeaderMap) -> HttpResult {
    state.authorize(&headers)?;
    let refresh = state
        .store
        .refresh_state(state.config.term_start)
        .await
        .map_err(|error| {
            eprintln!("Import status: {error:?}");
            bad(
                StatusCode::INTERNAL_SERVER_ERROR,
                "Could not read refresh state",
            )
        })?;
    Ok(Json(json!(refresh)))
}

pub(crate) fn router(state: AdminState) -> Router {
    Router::new()
        .route("/imports/status", get(status))
        .route("/imports/{id}", post(begin).delete(cancel))
        .route("/imports/{id}/evidence", post(evidence))
        .layer(DefaultBodyLimit::max(32 * 1024 * 1024))
        .with_state(state)
}
"""Operator commands and the NDJSON API worker used by the Rust application."""

import argparse
import json
import logging
import os
import sys
from datetime import date
from pathlib import Path
from urllib.parse import urlsplit

import httpx
from dotenv import load_dotenv

from exposed.operator import OperatorError, run_import
from exposed.source import SourceClient, SourceError


def source_worker(source: SourceClient) -> int:
    for line in sys.stdin:
        try:
            response = source.fetch(json.loads(line))
        except (ValueError, KeyError, TypeError, SourceError) as exc:
            print(json.dumps({"error": str(exc)}), flush=True)
            return 1
        print(json.dumps(response), flush=True)
    return 0


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(
        description="Fetch Parliament evidence for the Rust application"
    )
    commands = parser.add_subparsers(dest="command", required=True)
    commands.add_parser("source", help="Serve raw API requests over NDJSON stdin/stdout")
    for name in ("import-members", "import-declarations", "initialize"):
        command = commands.add_parser(name)
        command.add_argument(
            "--term-start", help="Configured Parliament election date (YYYY-MM-DD)"
        )
        command.add_argument(
            "--app-url", help="Rust operator API URL (default http://127.0.0.1:7000)"
        )
    args = parser.parse_args(argv)
    logging.basicConfig(level=logging.INFO, format="%(levelname)s %(message)s")
    logging.getLogger("httpx").setLevel(logging.WARNING)
    with httpx.Client(
        timeout=httpx.Timeout(30, connect=10),
        headers={"Accept": "application/json", "User-Agent": "exposed-api-client/0.1"},
    ) as client:
        source = SourceClient(client)
        if args.command == "source":
            return source_worker(source)
        # Explicit working-directory configuration only. This package never reads DATABASE_URL.
        load_dotenv(Path.cwd() / ".env", override=False)
        term = args.term_start or os.environ.get("PARLIAMENT_TERM_START")
        if term is not None:
            try:
                if date.fromisoformat(term).isoformat() != term:
                    raise ValueError
            except ValueError:
                parser.error("--term-start/PARLIAMENT_TERM_START must be YYYY-MM-DD")
        app_url = args.app_url or os.environ.get("EXPOSED_APP_URL", "http://127.0.0.1:7000")
        parsed_url = urlsplit(app_url)
        if parsed_url.scheme not in {"http", "https"} or not parsed_url.netloc:
            parser.error("--app-url/EXPOSED_APP_URL must be an HTTP or HTTPS URL")
        headers = {}
        if token := os.environ.get("EXPOSED_IMPORT_TOKEN"):
            headers["Authorization"] = f"Bearer {token}"
        with httpx.Client(base_url=app_url, headers=headers, timeout=330) as app:
            try:
                kind = {
                    "import-members": "members",
                    "import-declarations": "declarations",
                    "initialize": "initialize",
                }[args.command]
                result = run_import(kind, term, app, source)
            except (SourceError, OperatorError) as exc:
                print(json.dumps({"status": "failed", "error": str(exc)}))
                return 1
            except KeyboardInterrupt:
                print(json.dumps({"status": "failed", "error": "Interrupted"}))
                return 130
        print(json.dumps(result, sort_keys=True))
        return 0
"""Parliament HTTP transport. Responses remain unmodified source evidence."""

import logging
import time
from collections.abc import Callable
from datetime import UTC, datetime
from email.utils import parsedate_to_datetime
from typing import Any

import httpx

MEMBERS = "https://members-api.parliament.uk"
INTERESTS = "https://interests-api.parliament.uk"


class SourceError(Exception):
    """A bounded API request could not complete."""


class SourceClient:
    def __init__(self, client: httpx.Client, *, sleep: Callable[[float], None] = time.sleep):
        self.client = client
        self.sleep = sleep

    def _get(self, url: str, params: httpx.QueryParams) -> Any:
        for attempt in range(4):
            self.sleep(0.2)
            response = None
            try:
                response = self.client.get(url, params=params)
            except httpx.TransportError:
                if attempt == 3:
                    raise SourceError("Parliament API transport failure") from None
            else:
                if response.status_code == 200:
                    try:
                        return response.json()
                    except ValueError:
                        raise SourceError("Parliament API returned invalid JSON") from None
                if response.status_code != 429 and response.status_code < 500 or attempt == 3:
                    raise SourceError(f"Parliament API returned HTTP {response.status_code}")
            delay = 2**attempt
            if response is not None and (retry := response.headers.get("Retry-After")):
                try:
                    delay = float(retry)
                except ValueError:
                    try:
                        delay = (parsedate_to_datetime(retry) - datetime.now(UTC)).total_seconds()
                    except ValueError, TypeError, OverflowError:
                        pass
            logging.warning("Retrying Parliament request (attempt %s/4)", attempt + 2)
            self.sleep(min(30, max(0, delay)))
        raise SourceError("Parliament API retries exhausted")

    def fetch(self, request: dict[str, Any]) -> dict[str, Any]:
        operation = request["operation"]
        offset = request.get("offset", 0)
        if operation in {"current-members", "member-candidates"}:
            params = httpx.QueryParams({"skip": offset, "take": 100})
            if operation == "current-members":
                params = params.set("House", 1).set("IsCurrentMember", "true")
            else:
                params = params.set(
                    "MembershipInDateRange.WasMemberOnOrAfter", request["term_start"]
                )
                params = params.set("MembershipInDateRange.WasMemberOnOrBefore", request["as_of"])
                params = params.set("MembershipInDateRange.WasMemberOfHouse", 1)
            url = MEMBERS + "/api/Members/Search"
        elif operation == "member-histories":
            ids = request["ids"]
            if not 1 <= len(ids) <= 100:
                raise SourceError("History requests require 1 to 100 IDs")
            params = httpx.QueryParams([("ids", str(value)) for value in sorted(ids)])
            url = MEMBERS + "/api/Members/History"
        elif operation in {"declarations", "parent"}:
            params = httpx.QueryParams(
                {
                    "Type": "Commons",
                    "ExcludeExpired": "false",
                    "ExpandChildInterests": "false",
                    "Skip": offset,
                    "Take": 100,
                    "MemberId": request["member"],
                }
            )
            if operation == "parent":
                params = params.set("InterestIds", request["parent"])
            url = INTERESTS + "/api/v2/Interests"
        else:
            raise SourceError(f"Unknown source operation: {operation}")
        payload = self._get(url, params)
        return {
            "payload": payload,
            "fetched_at": datetime.now(UTC).isoformat(),
            "context": f"{operation} offset {offset}",
        }
"""Submit source evidence and wait for Rust's next request or committed result."""

import logging
import time
from typing import Any
from uuid import uuid4

import httpx

from exposed.source import SourceClient


class OperatorError(Exception):
    """The Rust application could not complete the import."""


def _post(app: httpx.Client, path: str, body: dict[str, Any]) -> dict[str, Any]:
    # Same session/sequence/body on every retry: a lost acknowledgement must not
    # publish a batch twice or start a second run.
    for attempt in range(3):
        try:
            response = app.post(path, json=body)
        except httpx.TransportError:
            if attempt == 2:
                raise OperatorError("Cannot reach the Rust import interface") from None
            time.sleep(2**attempt)
            continue
        try:
            message = response.json()
        except ValueError:
            raise OperatorError(
                f"Rust returned an invalid response (HTTP {response.status_code})"
            ) from None
        if not isinstance(message, dict):
            raise OperatorError("Rust returned an invalid response envelope")
        if not response.is_success or "error" in message:
            raise OperatorError(message.get("error", f"Rust returned HTTP {response.status_code}"))
        return message
    raise OperatorError("Rust request retries exhausted")


def run_import(
    kind: str, term_start: str | None, app: httpx.Client, source: SourceClient
) -> dict[str, Any]:
    path = f"/imports/{uuid4()}"
    try:
        message = _post(app, path, {"kind": kind, "term_start": term_start})
        while "request" in message:
            evidence = source.fetch(message["request"])
            message = _post(
                app, path + "/evidence", {"sequence": message["sequence"], "response": evidence}
            )
        if not isinstance(message.get("result"), dict):
            raise OperatorError("Rust response has no import result")
        return message["result"]
    finally:
        try:
            app.delete(path, timeout=5)
        except httpx.HTTPError:
            logging.warning("Unable to close import session; it will expire automatically")

