import json
from collections import Counter
from collections.abc import Sequence
from datetime import date, datetime
from decimal import Decimal

from pydantic import JsonValue

from exposed.core.errors import DeclarationParseError, ParentRequired
from exposed.core.models import DisplayName, Model, PositiveID


def canonical_json(value: JsonValue) -> str:
    """Compare evidence without conflating JSON booleans and numbers."""
    return json.dumps(value, sort_keys=True, separators=(",", ":"))


class PublishedVersion(Model):
    published_on: date
    content: JsonValue


def latest_version(versions: Sequence[PublishedVersion]) -> int:
    """Choose the newest publication; equally recent conflicting evidence is invalid."""
    if not versions:
        raise DeclarationParseError("versions", [], "expected at least one published version")
    newest = max(version.published_on for version in versions)
    latest = [i for i, version in enumerate(versions) if version.published_on == newest]
    first = latest[0]
    if any(
        canonical_json(versions[i].content) != canonical_json(versions[first].content)
        for i in latest[1:]
    ):
        raise DeclarationParseError(
            "versions",
            [v.content for v in versions],
            "conflicting versions at latest register date",
        )
    return first


type FunderName = str | None | DeclarationParseError


def preferred_funder(
    *,
    ultimate_payer: FunderName = None,
    donor: FunderName = None,
    payer: FunderName = None,
    group_donor: FunderName = None,
) -> str | None:
    """Prefer the ultimate payer, then direct donor/payer, then a grouped donor.

    A name-decoding failure matters only if that candidate is needed. This retains
    the existing treatment of malformed, unused fallback names without moving
    source field decoding into the domain.
    """
    for name in (ultimate_payer, donor, payer, group_donor):
        if isinstance(name, DeclarationParseError):
            raise name
        if name:
            return name
    return None


class Funder(Model):
    funder_name: str | None
    funder_kind: str | None = None
    company_number: str | None = None


class FundingEntry(Funder):
    amount: Decimal | None
    currency: str | None
    payment_type: str | None


class DeclarationIdentity(Model):
    id: PositiveID
    member_source_id: PositiveID
    category_id: PositiveID
    category_name: DisplayName
    registration_date: date | None = None


class Declaration(DeclarationIdentity):
    """A fully interpreted declaration, ready for atomic publication."""

    funding: tuple[FundingEntry, ...]
    payer: str | None

    def has_same_funding(self, previous: Sequence[FundingEntry]) -> bool:
        """Funding identity ignores order, while equal entries retain their multiplicity."""
        return Counter(self.funding) == Counter(previous)


class DeclarationDraft(DeclarationIdentity):
    """Complete local funding interpretation that may still require a parent payer."""

    funding: tuple[FundingEntry, ...]
    payer: str | None
    parent_id: PositiveID | None = None
    ultimate_payer_differs: bool = False

    def accept(self, *, parent: Declaration | None = None) -> Declaration:
        funding, payer = self.funding, self.payer
        needs_parent = (
            self.parent_id is not None
            and not self.ultimate_payer_differs
            and (
                any(entry.funder_name is None for entry in funding)
                or (not funding and payer is None)
            )
        )
        if needs_parent and self.parent_id is not None:
            if parent is None:
                raise ParentRequired(self.parent_id)
            if parent.id != self.parent_id or parent.member_source_id != self.member_source_id:
                raise DeclarationParseError(
                    "parent_id", self.parent_id, "parent identity or member mismatch"
                )
            if parent.payer is None:
                raise DeclarationParseError(
                    "parent_id", self.parent_id, "required parent payer is absent"
                )
            payer = payer or parent.payer
            funding = tuple(
                entry.model_copy(update={"funder_name": entry.funder_name or parent.payer})
                for entry in funding
            )
        return Declaration(
            id=self.id,
            member_source_id=self.member_source_id,
            category_id=self.category_id,
            category_name=self.category_name,
            registration_date=self.registration_date,
            funding=funding,
            payer=payer,
        )


class RetrievedDeclaration(Model):
    """Transient source response and retrieval context; never persisted."""

    identifier: JsonValue
    payload: JsonValue
    fetched_at: datetime
    context: str

    @property
    def source_id(self) -> int | None:
        if isinstance(self.identifier, int) and not isinstance(self.identifier, bool):
            return self.identifier
        return None
"""Refresh declarations through source evidence and atomic publication ports."""

import logging
from datetime import date

from exposed.core.declaration_ports import DeclarationSource, DeclarationStore
from exposed.core.declarations import (
    Declaration,
    RetrievedDeclaration,
    canonical_json,
)
from exposed.core.errors import (
    DeclarationParseError,
    ImportFailed,
    ImportValidationError,
    ParentRequired,
    safe_error,
)

logger = logging.getLogger(__name__)


def refresh_declarations(
    term_start: date,
    source: DeclarationSource,
    store: DeclarationStore,
) -> dict[str, object]:
    try:
        members = store.cohort(term_start)
        if not members:
            raise ImportValidationError("No stored Commons cohort for the configured term")
        accepted = 0
        sources = DeclarationSources(source)
        processed: set[int] = set()
        for source_member_id, member_id in members.items():
            with store.refresh_member() as writer:
                for batch in source.declarations(source_member_id):
                    for record in batch:
                        sources.remember(record)
                    for record in batch:
                        source_id = record.source_id
                        if source_id is not None:
                            if source_id in processed:
                                continue
                            processed.add(source_id)
                        try:
                            declaration = sources.resolve(record, source_member_id)
                        except DeclarationParseError as exc:
                            logger.error(
                                "Rejected declaration %s (member %s, %s): %s",
                                record.identifier,
                                source_member_id,
                                record.context,
                                exc,
                            )
                            continue
                        writer.write_declaration(member_id, declaration, record.fetched_at)
                        accepted += 1
            logger.info("Committed declarations for member %s", source_member_id)
        return {
            "status": "succeeded",
            "term_start": term_start.isoformat(),
            "members": len(members),
            "declarations": accepted,
        }
    except BaseException as exc:
        raise ImportFailed(safe_error(exc), interrupted=isinstance(exc, KeyboardInterrupt)) from exc


class DeclarationSources:
    """Resolve parent declarations within this refresh, regardless of delivery order."""

    def __init__(self, source: DeclarationSource):
        self.source = source
        self.records: dict[int, RetrievedDeclaration] = {}

    def remember(self, record: RetrievedDeclaration) -> None:
        source_id = record.source_id
        if source_id is None:
            return
        if source_id in self.records:
            if canonical_json(self.records[source_id].payload) != canonical_json(record.payload):
                raise ImportValidationError(f"Conflicting duplicate declaration {source_id}")
            logger.warning("Duplicate declaration %s; identical content collapsed", source_id)
        else:
            self.records[source_id] = record

    def resolve(
        self,
        record: RetrievedDeclaration,
        member_id: int,
        ancestors: frozenset[int] = frozenset(),
    ) -> Declaration:
        draft = self.source.interpret(record)
        if draft.id != record.source_id:
            raise DeclarationParseError("id", record.identifier, "source identity mismatch")
        if draft.id in ancestors:
            raise DeclarationParseError("parent_id", draft.id, "cyclic parent relationship")
        if draft.member_source_id != member_id:
            raise DeclarationParseError(
                "member_source_id", draft.member_source_id, "belongs to another member"
            )
        try:
            return draft.accept()
        except ParentRequired as required:
            parent_id = required.source_id
            if parent_id not in self.records:
                for parent in self.source.parent_declarations(member_id, parent_id):
                    self.remember(parent)
            if parent_id not in self.records:
                raise DeclarationParseError(
                    "parent_id", parent_id, "parent was not returned"
                ) from required
            parent = self.resolve(self.records[parent_id], member_id, ancestors | {draft.id})
            return draft.accept(parent=parent)

