use std::{collections::HashMap, str::FromStr};

use bigdecimal::BigDecimal;
use chrono::{DateTime, NaiveDate, NaiveDateTime};
use serde::Deserialize;
use serde_json::{Map, Value};

use crate::imports::core::{
    ImportError, Result,
    declarations::{Draft, FunderCandidates, Funding, funder_attribution, latest_version},
};

pub(crate) fn invalid(path: &str, value: &Value, message: &str) -> ImportError {
    ImportError::Rejected(format!("{path}: {message}; input={value}"))
}

pub(crate) fn source_date(value: &Value, path: &str) -> Result<NaiveDate> {
    let text = value
        .as_str()
        .ok_or_else(|| invalid(path, value, "expected an ISO date"))?;
    if let Ok(date) = NaiveDate::parse_from_str(text, "%Y-%m-%d") {
        return Ok(date);
    }
    if let Ok(date) = DateTime::parse_from_rfc3339(text) {
        return Ok(date.date_naive());
    }
    for format in ["%Y-%m-%dT%H:%M:%S%.f", "%Y-%m-%d %H:%M:%S%.f"] {
        if let Ok(date) = NaiveDateTime::parse_from_str(text, format) {
            return Ok(date.date());
        }
    }
    Err(invalid(path, value, "expected an ISO date or datetime"))
}

fn positive(value: &Value, path: &str) -> Result<i32> {
    value
        .as_i64()
        .and_then(|n| i32::try_from(n).ok())
        .filter(|n| *n > 0)
        .ok_or_else(|| invalid(path, value, "expected a positive integer"))
}

fn nonblank(value: &Value, path: &str) -> Result<String> {
    value
        .as_str()
        .filter(|s| !s.trim().is_empty())
        .map(str::to_owned)
        .ok_or_else(|| invalid(path, value, "expected a nonblank string"))
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Field {
    name: String,
    #[serde(rename = "type")]
    kind: Option<String>,
    type_info: Option<Map<String, Value>>,
    #[serde(default)]
    value: Value,
    values: Option<Vec<Vec<Field>>>,
}

impl Field {
    fn text(&self, path: &str) -> Result<Option<String>> {
        if self.value.is_null() {
            return Ok(None);
        }
        self.value
            .as_str()
            .map(|s| (!s.trim().is_empty()).then(|| s.to_owned()))
            .ok_or_else(|| invalid(path, &self.value, "expected a string"))
    }

    fn check_shape(&self, path: &str, allowed: bool, nested: bool) -> Result<()> {
        let currency = self
            .type_info
            .as_ref()
            .is_some_and(|m| m.contains_key("currencyCode"));
        let financial =
            ["Value", "PaymentType", "Donors"].contains(&self.name.as_str()) || currency;
        if financial
            && (!allowed || (currency && self.name != "Value") || (nested && self.name == "Donors"))
        {
            return Err(invalid(
                path,
                &self.value,
                "unsupported funding field or nesting",
            ));
        }
        for (i, group) in self.values.iter().flatten().enumerate() {
            if self.name == "Donors" && group.is_empty() {
                return Err(invalid(path, &self.value, "empty donor group"));
            }
            for (j, field) in group.iter().enumerate() {
                field.check_shape(
                    &format!("{path}.values.{i}.{j}.{}", field.name),
                    allowed && self.name == "Donors",
                    true,
                )?;
            }
        }
        Ok(())
    }
}

fn funding(fields: &[Field], path: &str, donor_group: bool) -> Result<Funding> {
    let index: HashMap<_, _> = fields
        .iter()
        .enumerate()
        .map(|(i, f)| (f.name.as_str(), (i, f)))
        .collect();
    if index.len() != fields.len() {
        return Err(ImportError::Rejected(format!(
            "{path}: repeated field names"
        )));
    }
    let text = |name: &str| -> Result<Option<String>> {
        match index.get(name) {
            Some((i, f)) => f.text(&format!("{path}.{i}.{name}.value")),
            None => Ok(None),
        }
    };
    let mut amount = None;
    let mut currency = None;
    if let Some((i, value)) = index.get("Value") {
        let location = format!("{path}.{i}.Value");
        if value.kind.as_deref() != Some("Decimal") {
            return Err(invalid(
                &location,
                &value.value,
                "expected Decimal monetary field",
            ));
        }
        if !value.value.is_null() {
            let raw = match &value.value {
                Value::String(text) => text.clone(),
                Value::Number(number) => {
                    let raw = number.to_string();
                    // Python accepts arbitrary-size JSON integers, but rejects JSON floats.
                    if raw.contains(['.', 'e', 'E']) {
                        return Err(invalid(&location, &value.value, "unsupported amount"));
                    }
                    raw
                }
                _ => return Err(invalid(&location, &value.value, "unsupported amount")),
            };
            let unsigned = raw.strip_prefix('-').unwrap_or(&raw);
            let parts: Vec<_> = unsigned.split('.').collect();
            if parts.len() > 2
                || parts
                    .iter()
                    .any(|p| p.is_empty() || !p.bytes().all(|c| c.is_ascii_digit()))
            {
                return Err(invalid(&location, &value.value, "unsupported amount"));
            }
            amount = Some(
                BigDecimal::from_str(&raw)
                    .map_err(|_| invalid(&location, &value.value, "unsupported amount"))?,
            );
        }
        if let Some(code) = value
            .type_info
            .as_ref()
            .and_then(|m| m.get("currencyCode"))
            .filter(|v| !v.is_null())
        {
            currency = Some(
                code.as_str()
                    .ok_or_else(|| invalid(&location, code, "expected a currency string"))?
                    .to_owned(),
            );
        }
    }
    let (funder_name, funder_kind, company_number) = funder_attribution(
        FunderCandidates {
            ultimate_payer: text("UltimatePayerName"),
            donor: text("DonorName"),
            payer: text("PayerName"),
            group_donor: if donor_group { text("Name") } else { Ok(None) },
        },
        text("DonorStatus"),
        text("DonorCompanyIdentifier"),
    )?;
    Ok(Funding {
        funder_name,
        funder_kind,
        company_number,
        amount,
        currency,
        payment_type: text("PaymentType")?,
    })
}

pub(crate) fn interpret(raw: &Value) -> Result<Draft> {
    let id = positive(&raw["id"], "id")?;
    let member_source_id = positive(
        &raw["registrant"]["memberDetail"]["id"],
        "registrant.memberDetail.id",
    )?;
    if raw["registrant"]["type"] != "Member" || raw["category"]["type"] != "Commons" {
        return Err(invalid(
            "registrant/category",
            raw,
            "expected a Commons Member declaration",
        ));
    }
    let category_id = positive(&raw["category"]["id"], "category.id")?;
    let category_name = nonblank(&raw["category"]["name"], "category.name")?;
    let parent_id = if raw["parentInterestId"].is_null() {
        None
    } else {
        Some(positive(&raw["parentInterestId"], "parentInterestId")?)
    };
    let versions = raw["versions"]
        .as_array()
        .ok_or_else(|| invalid("versions", &raw["versions"], "expected versions"))?;
    let published = versions
        .iter()
        .enumerate()
        .map(|(i, v)| {
            let date = source_date(
                &v["register"]["publishedDate"],
                &format!("versions.{i}.register.publishedDate"),
            )?;
            let mut content = v
                .as_object()
                .ok_or_else(|| invalid("versions", v, "expected version object"))?
                .clone();
            content.remove("register");
            content.remove("links");
            Ok((date, Value::Object(content)))
        })
        .collect::<Result<Vec<_>>>()?;
    let selected = latest_version(&published)?;
    let version = &versions[selected];
    let path = format!("versions.{selected}.fields");
    let fields: Vec<Field> = serde_json::from_value(version["fields"].clone())
        .map_err(|e| invalid(&path, &version["fields"], &e.to_string()))?;
    let mut entries = Vec::new();
    for (i, field) in fields.iter().enumerate() {
        field.check_shape(&format!("{path}.{i}.{}", field.name), true, false)?;
    }
    if fields
        .iter()
        .any(|f| ["Value", "PaymentType"].contains(&f.name.as_str()))
    {
        entries.push(funding(&fields, &path, false)?);
    }
    for (i, field) in fields
        .iter()
        .enumerate()
        .filter(|(_, f)| f.name == "Donors")
    {
        let groups = field
            .values
            .as_ref()
            .ok_or_else(|| invalid(&path, &field.value, "expected donor groups"))?;
        for (j, group) in groups.iter().enumerate() {
            entries.push(funding(
                group,
                &format!("{path}.{i}.Donors.values.{j}"),
                true,
            )?);
        }
    }
    let payer = funding(&fields, &path, false)?.funder_name;
    let mut ultimate_payer_differs = false;
    if parent_id.is_some() {
        if let Some(field) = fields.iter().find(|f| f.name == "IsUltimatePayerDifferent") {
            if !field.value.is_null() && !field.value.is_boolean() {
                return Err(invalid(&path, &field.value, "expected a boolean"));
            }
            ultimate_payer_differs = field.value == true;
        }
    }
    let registration_date = if version["registrationDate"].is_null() {
        None
    } else {
        Some(source_date(
            &version["registrationDate"],
            "registrationDate",
        )?)
    };
    Ok(Draft {
        id,
        member_source_id,
        category_id,
        category_name,
        registration_date,
        funding: entries,
        payer,
        parent_id,
        ultimate_payer_differs,
    })
}
"""Decode Parliament JSON at the HTTP edge; keep source aliases out of the core."""

from datetime import date, datetime
from typing import Annotated, Self

from pydantic import BeforeValidator, ConfigDict, Field, RootModel

from exposed.core.models import (
    DisplayName,
    HouseNumber,
    MemberProfile,
    Model,
    PositiveID,
)
from exposed.core.models import (
    HouseMembership as DomainHouseMembership,
)
from exposed.core.models import (
    MemberHistory as DomainMemberHistory,
)


def calendar_date(value: str) -> date:
    """Retain the source's calendar date, discarding time without timezone conversion."""
    try:
        return datetime.fromisoformat(value).date()
    except (ValueError, TypeError) as exc:
        raise ValueError("expected an ISO date or datetime") from exc


type SourceDate = Annotated[date, BeforeValidator(calendar_date)]


class HouseMembership(DomainHouseMembership):
    start_date: SourceDate = Field(validation_alias="membershipStartDate")
    end_date: SourceDate | None = Field(default=None, validation_alias="membershipEndDate")


class MemberHistory(DomainMemberHistory):
    parliament_member_id: PositiveID = Field(validation_alias="id")
    house_memberships: tuple[
        Annotated[DomainHouseMembership, BeforeValidator(HouseMembership.model_validate)], ...
    ] = Field(validation_alias="houseMembershipHistory", min_length=1)

    def to_history(self) -> DomainMemberHistory:
        return DomainMemberHistory(
            parliament_member_id=self.parliament_member_id,
            house_memberships=tuple(
                DomainHouseMembership(
                    house=membership.house,
                    start_date=membership.start_date,
                    end_date=membership.end_date,
                )
                for membership in self.house_memberships
            ),
        )


class PartyResponse(Model):
    id: PositiveID | None = None
    name: str | None = None


class LatestMembershipResponse(Model):
    house: HouseNumber
    membership_from: str | None = Field(default=None, validation_alias="membershipFrom")


class MemberResponse(Model):
    """Only the profile fields we consume from Parliament's nested response."""

    id: PositiveID
    name: DisplayName = Field(validation_alias="nameDisplayAs")
    party: PartyResponse | None = Field(default=None, validation_alias="latestParty")
    latest_membership: LatestMembershipResponse = Field(validation_alias="latestHouseMembership")

    def to_profile(self) -> MemberProfile:
        return MemberProfile(
            parliament_member_id=self.id,
            name=self.name,
            party_id=self.party.id if self.party else None,
            party_name=self.party.name if self.party else None,
            latest_house=self.latest_membership.house,
            latest_membership_from=self.latest_membership.membership_from,
        )


class ResponseItem[T](Model):
    """Parliament wraps each resource in a value field alongside unused metadata."""

    value: T


class SearchResponse(Model):
    items: tuple[ResponseItem[MemberResponse], ...]
    total_results: Annotated[int, Field(ge=0)] = Field(validation_alias="totalResults")
    skip: Annotated[int, Field(ge=0)]


class HistoryResponse(RootModel[tuple[ResponseItem[MemberHistory], ...]]):
    model_config = ConfigDict(strict=True, frozen=True)


class SearchPage(Model):
    """One page of profiles; collection checks belong to the importer."""

    members: tuple[MemberProfile, ...]
    total_results: Annotated[int, Field(ge=0)]
    skip: Annotated[int, Field(ge=0)]

    @classmethod
    def from_json(cls, payload: str | bytes) -> Self:
        response = SearchResponse.model_validate_json(payload)
        return cls(
            members=tuple(item.value.to_profile() for item in response.items),
            total_results=response.total_results,
            skip=response.skip,
        )


class HistoryBatch(Model):
    """Histories in response order, retaining duplicates for the importer to check."""

    histories: tuple[MemberHistory, ...]

    @classmethod
    def from_json(cls, payload: str | bytes) -> Self:
        response = HistoryResponse.model_validate_json(payload)
        return cls(histories=tuple(item.value for item in response.root))
"""Refresh Commons membership through application-owned source and storage ports."""

import logging
from collections.abc import Iterable, Iterator
from datetime import date

from exposed.core.errors import ImportFailed, ImportValidationError, safe_error
from exposed.core.models import CommonsService, Member, MemberHistory, MemberProfile
from exposed.core.ports import MemberSource, RefreshStore

logger = logging.getLogger(__name__)


def match_histories[T: MemberHistory](member_ids: set[int], batch: tuple[T, ...]) -> dict[int, T]:
    """Match a history batch to its requested members before indexing it by ID."""
    histories: dict[int, T] = {}
    for history in batch:
        member_id = history.parliament_member_id
        if member_id in histories:
            raise ImportValidationError(f"Duplicate history for member {member_id}")
        histories[member_id] = history
    if histories.keys() != member_ids:
        raise ImportValidationError("History response does not contain all requested member IDs")
    return histories


def _unique_profiles(
    profiles: Iterable[MemberProfile], seen: dict[int, MemberProfile]
) -> Iterator[MemberProfile]:
    """Validate repeated identities within one source stream, including across pages."""
    for profile in profiles:
        member_id = profile.parliament_member_id
        if member_id in seen:
            if seen[member_id] != profile:
                raise ImportValidationError(f"Conflicting duplicate member {member_id}")
            logger.warning("Duplicate member %s; identical profile collapsed", member_id)
            continue
        seen[member_id] = profile
        yield profile


def _import_batches(
    store: RefreshStore,
    term_start: date,
    as_of: date,
    source: MemberSource,
) -> dict[str, int]:
    """Commit each candidate batch before requesting the next page from the source."""
    summary = dict.fromkeys(
        [
            "members",
            "current_commons",
            "former_commons",
            "inserted",
            "updated",
            "unchanged",
            "service_periods",
            "excluded_candidates",
        ],
        0,
    )

    logger.info("Fetching current Commons member IDs")
    current_ids = {
        member.parliament_member_id for member in _unique_profiles(source.current_commons(), {})
    }

    logger.info("Importing Commons service since %s in batches", term_start)
    seen_profiles: dict[int, MemberProfile] = {}
    for batch in source.commons_candidates(term_start, as_of):
        profiles = tuple(_unique_profiles(batch, seen_profiles))
        if not profiles:
            continue
        member_ids = {member.parliament_member_id for member in profiles}
        histories = match_histories(member_ids, source.member_histories(member_ids))
        with store.refresh_batch(term_start) as writer:
            for profile in profiles:
                member_id = profile.parliament_member_id
                current = member_id in current_ids
                service = CommonsService.from_history(
                    histories[member_id],
                    term_start=term_start,
                    as_of=as_of,
                    is_current_commons=current,
                )
                if not service.periods:
                    summary["excluded_candidates"] += 1
                    continue
                member = Member.from_profile(profile, is_current_commons=current)
                write_result = writer.write_member(member, service.periods)

                summary[write_result] += 1
                summary["members"] += 1
                summary["current_commons"] += current
                summary["former_commons"] += not current
                summary["service_periods"] += len(service.periods)

        logger.info(
            "Committed member batch (%s candidates; %s processed total)",
            len(profiles),
            len(seen_profiles),
        )

    if not current_ids <= seen_profiles.keys():
        raise ImportValidationError(
            "Current search contains members missing from historical search"
        )
    if not summary["members"]:
        raise ImportValidationError("No Commons service was found for the configured term")
    return summary


def refresh_members(
    term_start: date,
    as_of: date,
    source: MemberSource,
    store: RefreshStore,
) -> dict[str, object]:
    """Refresh a term on a fixed date, publishing completed batches independently."""
    try:
        if term_start > as_of:
            raise ImportValidationError("Term start cannot be after the import date")
        summary = _import_batches(store, term_start, as_of, source)
        return {
            "status": "succeeded",
            "term_start": term_start.isoformat(),
            "as_of": as_of.isoformat(),
            **summary,
        }
    except BaseException as exc:
        raise ImportFailed(safe_error(exc), interrupted=isinstance(exc, KeyboardInterrupt)) from exc

