"""Validated member values and Commons service rules, independent of source formats."""

from datetime import date
from itertools import pairwise
from typing import Annotated, Self

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator

from exposed.core.errors import ImportValidationError

type PositiveID = Annotated[int, Field(gt=0)]
type HouseNumber = Annotated[int, Field(ge=1, le=2)]
type DisplayName = Annotated[str, Field(pattern=r"\S")]


class Model(BaseModel):
    model_config = ConfigDict(strict=True, extra="ignore", frozen=True, validate_by_name=True)


class MemberProfile(Model):
    """Latest profile, independent of current Commons membership."""

    parliament_member_id: PositiveID
    name: DisplayName
    party_id: PositiveID | None = None
    party_name: str | None = None
    latest_house: HouseNumber
    latest_membership_from: str | None = None


class Member(MemberProfile):
    """Member fields persisted by the importer."""

    is_current_commons: bool

    @classmethod
    def from_profile(cls, profile: MemberProfile, *, is_current_commons: bool) -> Self:
        return cls(**profile.model_dump(), is_current_commons=is_current_commons)

    @model_validator(mode="after")
    def current_membership_is_commons(self) -> Self:
        if self.is_current_commons and self.latest_house != 1:
            raise ValueError(f"Member {self.parliament_member_id}: inconsistent latest House")
        return self


class HouseMembership(Model):
    house: HouseNumber
    start_date: date
    end_date: date | None = None


class MemberHistory(Model):
    parliament_member_id: PositiveID
    house_memberships: tuple[HouseMembership, ...] = Field(min_length=1)


class ServicePeriod(Model):
    parliament_member_id: PositiveID
    source_start_date: date
    source_end_date: date | None = None
    served_from: date
    served_until: date | None = None
    house: Annotated[int, Field(ge=1, le=1)] = 1

    @classmethod
    def from_membership(
        cls, member_id: int, membership: HouseMembership, *, term_start: date
    ) -> Self:
        return cls(
            parliament_member_id=member_id,
            source_start_date=membership.start_date,
            source_end_date=membership.end_date,
            served_from=max(membership.start_date, term_start),
            served_until=membership.end_date,
        )

    @model_validator(mode="after")
    def dates_describe_valid_service(self) -> Self:
        if self.served_from < self.source_start_date:
            raise ValueError("Service cannot begin before the source start date")
        if self.served_until != self.source_end_date:
            raise ValueError("Service end must match the source end date")
        if self.served_until is not None and self.served_until < self.served_from:
            raise ValueError(f"Member {self.parliament_member_id}: service ends before it starts")
        return self


class CommonsService(Model):
    """One member's Commons service during a term, observed on a fixed date."""

    parliament_member_id: PositiveID
    as_of: date
    is_current_commons: bool
    periods: tuple[ServicePeriod, ...]

    @classmethod
    def from_history(
        cls,
        history: MemberHistory,
        *,
        term_start: date,
        as_of: date,
        is_current_commons: bool,
    ) -> Self:
        # An end date is the date service ceased, so service ending on term_start is excluded.
        memberships_in_term = [
            membership
            for membership in history.house_memberships
            if membership.house == 1
            and membership.start_date <= as_of
            and (membership.end_date is None or membership.end_date > term_start)
        ]
        return cls(
            parliament_member_id=history.parliament_member_id,
            as_of=as_of,
            is_current_commons=is_current_commons,
            periods=tuple(
                ServicePeriod.from_membership(
                    history.parliament_member_id, membership, term_start=term_start
                )
                for membership in memberships_in_term
            ),
        )

    @field_validator("periods")
    @classmethod
    def sort_distinct_periods(cls, periods: tuple[ServicePeriod, ...]) -> tuple[ServicePeriod, ...]:
        return tuple(sorted(set(periods), key=lambda period: period.source_start_date))

    @model_validator(mode="after")
    def periods_do_not_overlap(self) -> Self:
        for previous, following in pairwise(self.periods):
            if previous.source_start_date == following.source_start_date:
                raise ValueError(f"Member {self.parliament_member_id}: conflicting service periods")
            if previous.served_until is None or following.served_from < previous.served_until:
                raise ValueError(f"Member {self.parliament_member_id}: overlapping service periods")
        return self

    @model_validator(mode="after")
    def service_matches_current_membership(self) -> Self:
        if self.is_current_commons and not self.periods:
            raise ValueError(
                f"Current member {self.parliament_member_id} has no service in this term"
            )
        active = any(
            period.served_until is None or period.served_until > self.as_of
            for period in self.periods
        )
        if active != self.is_current_commons:
            raise ValueError(
                f"Member {self.parliament_member_id}: history disagrees with current search"
            )
        return self


def validate_configured_term(term_start: date, stored_starts: set[date]) -> None:
    """This importer refreshes one Parliament; stored terms cannot silently roll over."""
    if stored_starts - {term_start}:
        raise ImportValidationError(
            "This database contains another term. This first version refreshes one configured "
            "Parliament; term rollover requires an explicit migration."
        )
"""PostgreSQL implementation of atomic Commons member batches."""

from collections.abc import Iterator, Sequence
from contextlib import contextmanager
from datetime import UTC, date, datetime, time
from uuid import UUID, uuid7

import psycopg
from psycopg import Connection
from psycopg.rows import DictRow, dict_row

from exposed.core.errors import StorageError
from exposed.core.models import Member, ServicePeriod, validate_configured_term
from exposed.core.ports import MemberWriter, WriteResult

type DatabaseConnection = Connection[DictRow]


def date_timestamp(value: date | None) -> datetime | None:
    """Store source calendar dates at midnight UTC regardless of the session timezone."""
    return datetime.combine(value, time.min, UTC) if value is not None else None


def ensure_term(conn: DatabaseConnection, term_start: date) -> UUID:
    dates = {
        row["term_start"].astimezone(UTC).date()
        for row in conn.execute("SELECT term_start FROM exposed.parliament_terms")
    }
    validate_configured_term(term_start, dates)
    return next(
        conn.execute(
            """INSERT INTO exposed.parliament_terms (id, term_start) VALUES (%s, %s)
           ON CONFLICT (term_start) DO UPDATE SET term_start = EXCLUDED.term_start
           RETURNING id""",
            (uuid7(), date_timestamp(term_start)),
        )
    )["id"]


def write_member(
    conn: DatabaseConnection,
    term_id: UUID,
    member: Member,
    periods: Sequence[ServicePeriod],
) -> WriteResult:
    previous = conn.execute(
        """SELECT parliament_member_id, name, party_id, party_name, latest_house,
                  latest_membership_from, is_current_commons
           FROM exposed.members WHERE parliament_member_id = %s""",
        (member.parliament_member_id,),
    ).fetchone()
    values = (
        member.parliament_member_id,
        member.name,
        member.party_id,
        member.party_name,
        member.latest_house,
        member.latest_membership_from,
        member.is_current_commons,
    )
    change = (
        "inserted"
        if previous is None
        else ("unchanged" if tuple(previous.values()) == values else "updated")
    )
    member_id = next(
        conn.execute(
            """INSERT INTO exposed.members (
               id, parliament_member_id, name, party_id, party_name, latest_house,
               latest_membership_from, is_current_commons
           ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
           ON CONFLICT (parliament_member_id) DO UPDATE SET
               name = EXCLUDED.name, party_id = EXCLUDED.party_id,
               party_name = EXCLUDED.party_name, latest_house = EXCLUDED.latest_house,
               latest_membership_from = EXCLUDED.latest_membership_from,
               is_current_commons = EXCLUDED.is_current_commons
           RETURNING id""",
            (uuid7(), *values),
        )
    )["id"]
    with conn.cursor() as cursor:
        cursor.executemany(
            """INSERT INTO exposed.member_terms (
                   id, member_id, term_id, house, source_start_date, source_end_date,
                   served_from, served_until
               ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
               ON CONFLICT (member_id, term_id, house, source_start_date) DO UPDATE SET
                   source_end_date = EXCLUDED.source_end_date,
                   served_from = EXCLUDED.served_from, served_until = EXCLUDED.served_until""",
            [
                (
                    uuid7(),
                    member_id,
                    term_id,
                    p.house,
                    date_timestamp(p.source_start_date),
                    date_timestamp(p.source_end_date),
                    date_timestamp(p.served_from),
                    date_timestamp(p.served_until),
                )
                for p in periods
            ],
        )
    conn.execute(
        """DELETE FROM exposed.member_terms
           WHERE member_id = %s AND term_id = %s
             AND NOT (source_start_date = ANY(%s))""",
        (member_id, term_id, [date_timestamp(p.source_start_date) for p in periods]),
    )
    return change


def connect(database_url: str) -> DatabaseConnection:
    return psycopg.Connection[DictRow].connect(
        database_url,
        autocommit=True,
        row_factory=dict_row,
        connect_timeout=10,
        application_name="exposed",
    )


def storage_error(exc: psycopg.Error) -> StorageError:
    # DSNs and server details can contain credentials; retain them only in the cause.
    code = exc.sqlstate or "unknown"
    return StorageError(f"Database operation failed ({type(exc).__name__}, SQLSTATE {code})")


class _PostgresWriter:
    def __init__(self, conn: DatabaseConnection, term_id: UUID):
        self.conn = conn
        self.term_id = term_id

    def write_member(self, member: Member, periods: Sequence[ServicePeriod]) -> WriteResult:
        return write_member(self.conn, self.term_id, member, periods)


class PostgresStore:
    """Use a composition-owned connection; own one transaction per member batch."""

    def __init__(self, conn: DatabaseConnection):
        self.conn = conn

    @contextmanager
    def refresh_batch(self, term_start: date) -> Iterator[MemberWriter]:
        try:
            with self.conn.transaction():
                term_id = ensure_term(self.conn, term_start)
                yield _PostgresWriter(self.conn, term_id)
        except psycopg.Error as exc:
            raise storage_error(exc) from exc
