        cursor.executemany(
            """INSERT INTO exposed.funding_entries (
                   id, source_declaration_id, funder_id, amount, currency, payment_type
               ) VALUES (%s, %s, %s, %s, %s, %s)""",
            [(uuid7(), declaration.id, *entry) for entry in funding],
